// ─── File: BrowserStorageDemo.java ───
package com.bank.storage;

import java.util.logging.*;

public class BrowserStorageDemo {
    private static final Logger log = Logger.getLogger(BrowserStorageDemo.class.getName());
    static final String BANK_NAME = "National Bank of India";

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        String rajeshJwt = "eyJhbGciOiJIUzI1NiJ9.rajesh.sig";
        XssScript attacker = new XssScript();

        // Strategy 1: localStorage — JavaScript can read it.
        TokenStorage local = new LocalStorageStrategy();
        local.store(rajeshJwt);
        String stolen1 = attacker.trySteal(local);
        if (stolen1 != null)
            log.severe("localStorage: XSS STOLE the token -> account takeover: " + stolen1);

        // Strategy 2: HttpOnly cookie — JavaScript cannot read it.
        TokenStorage cookie = new HttpOnlyCookieStrategy();
        cookie.store(rajeshJwt);
        String stolen2 = attacker.trySteal(cookie);
        if (stolen2 == null)
            log.info("HttpOnly cookie: XSS could NOT read the token -> safe from theft");

        // SameSite blocks automatic cross-site send.
        boolean sentCrossSite = ((HttpOnlyCookieStrategy) cookie).wouldSendOnCrossSiteRequest();
        log.info(() -> "HttpOnly cookie sent on cross-site request? " + sentCrossSite
            + " (SameSite=Strict blocks CSRF)");
    }
}

// ─── Would be in TokenStorage.java ───
interface TokenStorage {
    void store(String token);
    // Simulates whether page JavaScript (document.cookie / localStorage) can read it.
    String readableByJavaScript();
}

// ─── Would be in LocalStorageStrategy.java ───
class LocalStorageStrategy implements TokenStorage {
    private String token;
    @Override public void store(String token) { this.token = token; }
    @Override public String readableByJavaScript() { return token; } // fully readable by JS
}

// ─── Would be in HttpOnlyCookieStrategy.java ───
class HttpOnlyCookieStrategy implements TokenStorage {
    private String token;             // held by the browser, not exposed to JS
    @Override public void store(String token) { this.token = token; }
    @Override public String readableByJavaScript() { return null; } // HttpOnly hides it
    boolean wouldSendOnCrossSiteRequest() { return false; }          // SameSite=Strict
}

// ─── Would be in XssScript.java ───
class XssScript {
    // A malicious injected script can only read what JavaScript can read.
    String trySteal(TokenStorage storage) { return storage.readableByJavaScript(); }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tY-%1$tm-%1$td %1$tH:%1$tM:%1$tS.%1$tL %2$-7s [%3$s] %4$s%n",
            r.getMillis(), r.getLevel().getName(),
            r.getSourceClassName() == null ? "Unknown"
                : r.getSourceClassName().substring(r.getSourceClassName().lastIndexOf('.') + 1),
            r.getMessage());
    }
}
